import { useMemo, useState, type FormEvent, type ReactNode } from "react";
import {
  Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Bell, CalendarDays, Check,
  CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, ChevronsUpDown, CircleHelp,
  Clock3, Command, Download, FileCheck2, FileSpreadsheet, Filter, LayoutDashboard,
  ListChecks, LockKeyhole, Menu, MoreHorizontal, Search, Settings2, ShieldCheck,
  SlidersHorizontal, Sparkles, Users, Wallet, X,
} from "lucide-react";
import {
  Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Pie, PieChart,
  ResponsiveContainer, Tooltip as ChartTooltip, XAxis, YAxis,
} from "recharts";
import { toast } from "sonner";

import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Progress } from "@/components/ui/progress";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  activitySeed, compactINR, complianceTasks, currencyINR, departmentDistribution,
  employees as seedEmployees, payrollRuns as seedPayrollRuns, payrollTrend,
  todayIndian, type Activity as ActivityItem, type ComplianceStatus, type ComplianceTask,
  type Employee, type PayrollStatus,
} from "@/lib/workforce-demo";

type ViewKey = "Dashboard" | "Employees" | "Attendance" | "Departments" | "Payroll overview" | "Payroll runs" | "Payslips" | "Compliance dashboard" | "Obligations & tasks" | "Compliance calendar" | "Audits" | "Audit findings" | "Documents" | "Reports" | "Users & roles" | "Locations" | "Settings" | "Audit trail";

const navigation: { label: string; items: { name: ViewKey; icon: typeof LayoutDashboard }[] }[] = [
  { label: "OVERVIEW", items: [{ name: "Dashboard", icon: LayoutDashboard }] },
  { label: "WORKFORCE", items: [{ name: "Employees", icon: Users }, { name: "Attendance", icon: CalendarDays }, { name: "Departments", icon: Users }] },
  { label: "PAYROLL", items: [{ name: "Payroll overview", icon: Wallet }, { name: "Payroll runs", icon: FileSpreadsheet }, { name: "Payslips", icon: FileCheck2 }] },
  { label: "COMPLIANCE", items: [{ name: "Compliance dashboard", icon: ShieldCheck }, { name: "Obligations & tasks", icon: ListChecks }, { name: "Compliance calendar", icon: CalendarDays }] },
  { label: "AUDIT", items: [{ name: "Audits", icon: FileCheck2 }, { name: "Audit findings", icon: Activity }] },
  { label: "RESOURCES", items: [{ name: "Documents", icon: FileSpreadsheet }, { name: "Reports", icon: FileSpreadsheet }] },
  { label: "ADMINISTRATION", items: [{ name: "Users & roles", icon: Users }, { name: "Locations", icon: Settings2 }, { name: "Settings", icon: Settings2 }, { name: "Audit trail", icon: Activity }] },
];

const statusClass: Record<ComplianceStatus | Employee["status"] | PayrollStatus, string> = {
  "Completed": "bg-success-soft text-success",
  "Active": "bg-success-soft text-success",
  "Finalized": "bg-success-soft text-success",
  "Due soon": "bg-warning-soft text-warning",
  "Probation": "bg-warning-soft text-warning",
  "Awaiting approval": "bg-warning-soft text-warning",
  "Upcoming": "bg-information-soft text-information",
  "Processing": "bg-information-soft text-information",
  "On leave": "bg-muted text-muted-foreground",
  "Needs review": "bg-critical-soft text-critical",
  "Overdue": "bg-critical-soft text-critical",
};

function StatusPill({ children }: { children: keyof typeof statusClass }) {
  return <Badge className={`rounded-full border-0 px-2.5 py-1 font-medium ${statusClass[children]}`}>{children}</Badge>;
}

function InitialAvatar({ name, initials, size = "md" }: { name: string; initials: string; size?: "sm" | "md" }) {
  const tone = ["bg-information-soft text-information", "bg-success-soft text-success", "bg-warning-soft text-warning", "bg-accent text-accent-foreground"][[...name].reduce((sum, char) => sum + char.charCodeAt(0), 0) % 4];
  return <Avatar className={size === "sm" ? "h-8 w-8" : "h-10 w-10"}><AvatarFallback className={`text-xs font-semibold ${tone}`}>{initials}</AvatarFallback></Avatar>;
}

function SectionTitle({ title, action, onAction }: { title: string; action?: string; onAction?: () => void }) {
  return <div className="mb-5 flex items-center justify-between gap-3"><h2 className="text-base font-semibold">{title}</h2>{action && <Button variant="ghost" size="sm" className="text-muted-foreground" onClick={onAction}>{action}<ArrowRight className="ml-1 h-3.5 w-3.5" /></Button>}</div>;
}

function MetricCard({ title, value, note, icon: Icon, direction, color }: { title: string; value: string; note: string; icon: typeof Users; direction: "up" | "down" | "flat"; color: "blue" | "teal" | "amber" | "red" }) {
  const colorClass = { blue: "bg-information-soft text-information", teal: "bg-success-soft text-success", amber: "bg-warning-soft text-warning", red: "bg-critical-soft text-critical" }[color];
  const DirectionIcon = direction === "down" ? ArrowDownRight : ArrowUpRight;
  return (
    <section className="portal-surface min-w-0 rounded-lg p-5">
      <div className="flex items-start justify-between"><p className="text-sm text-muted-foreground">{title}</p><span className={`flex h-9 w-9 items-center justify-center rounded-lg ${colorClass}`}><Icon className="h-[18px] w-[18px]" /></span></div>
      <div className="mt-4 flex flex-wrap items-baseline gap-x-2 gap-y-1"><strong className="tabular-nums text-[27px] font-semibold leading-none">{value}</strong><span className={`inline-flex items-center gap-0.5 text-xs font-medium ${direction === "down" ? "text-success" : direction === "up" ? "text-information" : "text-muted-foreground"}`}>{direction !== "flat" && <DirectionIcon className="h-3 w-3" />}{note}</span></div>
      <p className="mt-2 text-xs text-muted-foreground">Compared with last month</p>
    </section>
  );
}

export function WorkforcePortal() {
  const [activeView, setActiveView] = useState<ViewKey>("Dashboard");
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [globalSearch, setGlobalSearch] = useState("");
  const [location, setLocation] = useState("All locations");
  const [employeeSearch, setEmployeeSearch] = useState("");
  const [employeeDepartment, setEmployeeDepartment] = useState("All departments");
  const [employeeStatus, setEmployeeStatus] = useState("All statuses");
  const [employees, setEmployees] = useState(seedEmployees);
  const [tasks, setTasks] = useState(complianceTasks);
  const [runs, setRuns] = useState(seedPayrollRuns);
  const [activities, setActivities] = useState(activitySeed);
  const [addEmployeeOpen, setAddEmployeeOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [newEmployeeName, setNewEmployeeName] = useState("");
  const [newEmployeeRole, setNewEmployeeRole] = useState("");
  const [newEmployeeDepartment, setNewEmployeeDepartment] = useState("Engineering");
  const [attendanceMonth, setAttendanceMonth] = useState("November 2026");
  const [attendanceMarks, setAttendanceMarks] = useState<Record<string, string>>({});

  const filteredEmployees = useMemo(() => employees.filter((employee) => {
    const matchesSearch = `${employee.name} ${employee.id} ${employee.role} ${employee.email}`.toLowerCase().includes(employeeSearch.toLowerCase());
    const matchesDepartment = employeeDepartment === "All departments" || employee.department === employeeDepartment;
    const matchesStatus = employeeStatus === "All statuses" || employee.status === employeeStatus;
    const matchesLocation = location === "All locations" || employee.location === location;
    return matchesSearch && matchesDepartment && matchesStatus && matchesLocation;
  }), [employees, employeeSearch, employeeDepartment, employeeStatus, location]);

  const globalResults = useMemo(() => globalSearch.trim() ? employees.filter((employee) => `${employee.name} ${employee.id} ${employee.department}`.toLowerCase().includes(globalSearch.toLowerCase())).slice(0, 4) : [], [employees, globalSearch]);

  const goTo = (view: ViewKey) => {
    setActiveView(view);
    setMobileNavOpen(false);
    setGlobalSearch("");
  };

  const recordActivity = (title: string, detail: string, icon: ActivityItem["icon"]) => {
    setActivities((current) => [{ title, detail, time: "Just now", icon }, ...current].slice(0, 6));
  };

  const createEmployee = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!newEmployeeName.trim() || !newEmployeeRole.trim()) return;
    const initials = newEmployeeName.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase();
    const id = `WOS-${1050 + employees.length - seedEmployees.length}`;
    const employee: Employee = {
      id, name: newEmployeeName.trim(), initials, role: newEmployeeRole.trim(), department: newEmployeeDepartment,
      location: location === "All locations" ? "Bengaluru" : location, type: "Full-time", joined: new Intl.DateTimeFormat("en-IN", { day: "2-digit", month: "short", year: "numeric" }).format(new Date()), status: "Probation",
      email: `${newEmployeeName.trim().toLowerCase().replace(/\s+/g, ".")}@northstar.example`,
    };
    setEmployees((current) => [employee, ...current]);
    recordActivity("New starter added", `${employee.name} · ${employee.department}`, "people");
    setNewEmployeeName(""); setNewEmployeeRole(""); setAddEmployeeOpen(false);
    setActiveView("Employees");
    toast.success(`${employee.name} added to the employee directory`);
  };

  const toggleTask = (task: ComplianceTask) => {
    const nextStatus: ComplianceStatus = task.status === "Completed" ? "Upcoming" : "Completed";
    setTasks((current) => current.map((item) => item.id === task.id ? { ...item, status: nextStatus } : item));
    recordActivity(nextStatus === "Completed" ? "Compliance item completed" : "Compliance item reopened", `${task.title} · ${task.location}`, "shield");
    toast.success(nextStatus === "Completed" ? "Task marked as complete" : "Task moved back to upcoming");
  };

  const updatePayrollStatus = (runId: string, status: PayrollStatus) => {
    setRuns((current) => current.map((run) => run.id === runId ? { ...run, status } : run));
    const run = runs.find((item) => item.id === runId);
    recordActivity(`Payroll ${status.toLowerCase()}`, `${run?.period ?? runId} · ${runId}`, "wallet");
    toast.success(`Payroll run ${runId} marked ${status.toLowerCase()}`);
  };

  const exportEmployees = () => {
    const rows = [["Employee ID", "Name", "Department", "Designation", "Location", "Status"], ...filteredEmployees.map((employee) => [employee.id, employee.name, employee.department, employee.role, employee.location, employee.status])];
    const csv = rows.map((row) => row.map((value) => `"${value.replaceAll('"', '""')}"`).join(",")).join("\n");
    const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" }));
    const anchor = document.createElement("a"); anchor.href = url; anchor.download = "northstar-employee-directory.csv"; anchor.click(); URL.revokeObjectURL(url);
    toast.success(`${filteredEmployees.length} employee records exported`);
  };

  const unreadCount = tasks.filter((task) => task.status === "Overdue" || task.status === "Due soon").length + 1;
  const activeCount = employees.filter((employee) => employee.status === "Active").length;
  const overdueCount = tasks.filter((task) => task.status === "Overdue").length;
  const pendingCount = tasks.filter((task) => task.status === "Upcoming" || task.status === "Due soon").length;

  return (
    <div className="portal flex min-h-screen bg-background text-foreground">
      {mobileNavOpen && <button aria-label="Close navigation" className="fixed inset-0 z-30 bg-foreground/30 lg:hidden" onClick={() => setMobileNavOpen(false)} />}
      <aside className={`portal-scrollbar fixed inset-y-0 left-0 z-40 flex flex-col overflow-x-hidden overflow-y-auto bg-sidebar text-sidebar-foreground transition-[width,transform] duration-200 lg:sticky lg:top-0 lg:h-screen lg:translate-x-0 ${sidebarCollapsed ? "w-[76px]" : "w-[250px]"} ${mobileNavOpen ? "translate-x-0" : "-translate-x-full"}`}>
        <div className={`flex h-[72px] shrink-0 items-center border-b border-sidebar-border ${sidebarCollapsed ? "justify-center px-3" : "gap-3 px-5"}`}>
          <div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground"><Sparkles className="h-[18px] w-[18px]" /></div>
          {!sidebarCollapsed && <div className="min-w-0"><p className="text-sm font-bold tracking-wide">workforce<span className="text-sidebar-primary">OS</span></p><p className="mt-0.5 text-[10px] text-sidebar-foreground/60">PEOPLE · PAYROLL · COMPLIANCE</p></div>}
          <Button variant="ghost" size="icon" className="ml-auto hidden h-8 w-8 text-sidebar-foreground/60 hover:bg-sidebar-accent hover:text-sidebar-foreground lg:inline-flex" aria-label={sidebarCollapsed ? "Expand navigation" : "Collapse navigation"} title={sidebarCollapsed ? "Expand navigation" : "Collapse navigation"} onClick={() => setSidebarCollapsed(!sidebarCollapsed)}><ChevronsUpDown className="h-4 w-4" /></Button>
        </div>
        <div className={`border-b border-sidebar-border py-4 ${sidebarCollapsed ? "px-3" : "px-4"}`}>
          <button className={`flex w-full items-center rounded-lg border border-sidebar-border bg-sidebar-accent/70 px-2.5 py-2 text-left ${sidebarCollapsed ? "justify-center" : "gap-2.5"}`} onClick={() => toast.message("Northstar Technologies is your active organisation") } title="Select organisation">
            <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md bg-sidebar-primary/15 text-xs font-bold text-sidebar-primary">N</span>
            {!sidebarCollapsed && <><span className="min-w-0 flex-1"><span className="block truncate text-xs font-semibold">Northstar Technologies</span><span className="mt-0.5 block truncate text-[10px] text-sidebar-foreground/60">Enterprise plan</span></span><ChevronDown className="h-3.5 w-3.5 shrink-0 text-sidebar-foreground/60" /></>}
          </button>
        </div>
        <nav aria-label="Main navigation" className="flex-1 space-y-5 px-3 py-5">
          {navigation.map((group) => <div key={group.label}>
            {!sidebarCollapsed && <p className="mb-2 px-2 text-[10px] font-semibold tracking-[0.12em] text-sidebar-foreground/45">{group.label}</p>}
            <div className="space-y-1">{group.items.map(({ name, icon: Icon }) => <Button key={name} variant="ghost" onClick={() => goTo(name)} title={sidebarCollapsed ? name : undefined} aria-current={activeView === name ? "page" : undefined} className={`h-9 w-full justify-start gap-3 px-2.5 text-xs font-medium ${sidebarCollapsed ? "justify-center px-0" : ""} ${activeView === name ? "bg-sidebar-primary/15 text-sidebar-primary hover:bg-sidebar-primary/20 hover:text-sidebar-primary" : "text-sidebar-foreground/75 hover:bg-sidebar-accent hover:text-sidebar-foreground"}`}><Icon className="h-[17px] w-[17px] shrink-0" />{!sidebarCollapsed && <span className="truncate">{name}</span>}</Button>)}</div>
          </div>)}
        </nav>
        <div className="m-3 rounded-lg border border-sidebar-border bg-sidebar-accent/60 p-3">
          <div className="flex items-center gap-2"><span className="flex h-7 w-7 items-center justify-center rounded-md bg-success/15 text-success"><ShieldCheck className="h-4 w-4" /></span>{!sidebarCollapsed && <span className="text-xs font-medium">Compliance health</span>}</div>
          {!sidebarCollapsed && <><div className="mt-3 flex items-baseline justify-between"><span className="text-lg font-semibold tabular-nums">92<span className="text-xs font-normal text-sidebar-foreground/60">/100</span></span><span className="text-[10px] text-success">Healthy</span></div><Progress value={92} className="mt-2 h-1.5 bg-sidebar-border [&>div]:bg-success" /></>}
        </div>
        <div className={`flex items-center border-t border-sidebar-border py-3 ${sidebarCollapsed ? "justify-center px-2" : "gap-2.5 px-4"}`}>
          <Avatar className="h-8 w-8"><AvatarFallback className="bg-sidebar-primary/20 text-xs font-semibold text-sidebar-primary">AS</AvatarFallback></Avatar>
          {!sidebarCollapsed && <><span className="min-w-0 flex-1"><span className="block truncate text-xs font-medium">Ananya Sharma</span><span className="block text-[10px] text-sidebar-foreground/55">HR administrator</span></span><MoreHorizontal className="h-4 w-4 text-sidebar-foreground/55" /></>}
        </div>
      </aside>

      <div className="min-w-0 flex-1">
        <header className="portal-glass sticky top-0 z-20 flex h-[68px] items-center justify-between gap-3 border-x-0 border-t-0 px-4 sm:px-6 xl:px-8">
          <div className="flex min-w-0 items-center gap-3">
            <Button variant="ghost" size="icon" aria-label="Open navigation" className="shrink-0 lg:hidden" onClick={() => setMobileNavOpen(true)}><Menu className="h-[18px] w-[18px]" /></Button>
            <div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex"><span>Workspace</span><ChevronRight className="h-3.5 w-3.5" /><span className="font-medium text-foreground">{activeView}</span></div>
            <span className="font-semibold sm:hidden">{activeView}</span>
          </div>
          <div className="flex items-center gap-2 sm:gap-3">
            <label className="relative hidden w-48 md:block xl:w-64"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input aria-label="Search employees" placeholder="Search anything…" value={globalSearch} onChange={(event) => setGlobalSearch(event.target.value)} className="h-9 border-border/80 bg-card/70 pl-9 pr-14 text-xs placeholder:text-muted-foreground/80" />{!globalSearch && <kbd className="absolute right-2.5 top-1/2 -translate-y-1/2 rounded border bg-background px-1.5 py-0.5 text-[9px] text-muted-foreground">⌘ K</kbd>}
              {globalResults.length > 0 && <div className="portal-surface absolute left-0 right-0 top-11 z-50 rounded-lg p-1 shadow-lg">{globalResults.map((employee) => <button key={employee.id} className="flex w-full items-center gap-2 rounded-md p-2 text-left hover:bg-muted" onClick={() => { goTo("Employees"); setEmployeeSearch(employee.name); }}><InitialAvatar name={employee.name} initials={employee.initials} size="sm" /><span className="min-w-0"><span className="block truncate text-xs font-medium">{employee.name}</span><span className="block text-[10px] text-muted-foreground">{employee.id} · {employee.department}</span></span></button>)}</div>}
            </label>
            <label className="hidden items-center gap-1.5 text-xs text-muted-foreground sm:flex"><span className="sr-only">Location filter</span><Settings2 className="h-3.5 w-3.5" /><select aria-label="Filter by location" className="max-w-32 cursor-pointer bg-transparent text-xs text-foreground outline-none" value={location} onChange={(event) => setLocation(event.target.value)}><option>All locations</option><option>Bengaluru</option><option>Mumbai</option><option>Hyderabad</option><option>Chennai</option><option>Pune</option><option>Kolkata</option></select></label>
            <Button variant="ghost" size="icon" className="relative h-9 w-9" aria-label="Notifications" onClick={() => setNotificationsOpen(true)}><Bell className="h-[18px] w-[18px]" /><span className="absolute right-1.5 top-1.5 h-2 w-2 rounded-full bg-critical ring-2 ring-background" /></Button>
            <div className="flex h-8 w-8 items-center justify-center rounded-full bg-information-soft text-[10px] font-bold text-information sm:hidden">AS</div>
            <div className="hidden items-center gap-2 sm:flex"><Avatar className="h-8 w-8"><AvatarFallback className="bg-information-soft text-xs font-semibold text-information">AS</AvatarFallback></Avatar><span className="hidden text-xs font-medium lg:inline">Ananya Sharma</span></div>
          </div>
        </header>

        <main className="mx-auto w-full max-w-[1600px] px-4 pb-10 pt-7 sm:px-6 sm:pt-8 xl:px-9">
          {activeView === "Dashboard" && <DashboardView employees={employees} tasks={tasks} runs={runs} activities={activities} onNavigate={goTo} onToggleTask={toggleTask} />}
          {activeView === "Employees" && <EmployeesView employees={filteredEmployees} total={employees.length} search={employeeSearch} onSearch={setEmployeeSearch} department={employeeDepartment} onDepartment={setEmployeeDepartment} status={employeeStatus} onStatus={setEmployeeStatus} onAdd={() => setAddEmployeeOpen(true)} onExport={exportEmployees} onReset={() => { setEmployeeSearch(""); setEmployeeDepartment("All departments"); setEmployeeStatus("All statuses"); setLocation("All locations"); }} />}
          {activeView === "Attendance" && <AttendanceView employees={employees} month={attendanceMonth} onMonth={setAttendanceMonth} marks={attendanceMarks} onMark={(key, status) => setAttendanceMarks((current) => ({ ...current, [key]: status }))} />}
          {(activeView === "Payroll overview" || activeView === "Payroll runs" || activeView === "Payslips") && <PayrollView activeView={activeView} runs={runs} onStatus={updatePayrollStatus} />}
          {(activeView === "Compliance dashboard" || activeView === "Obligations & tasks" || activeView === "Compliance calendar") && <ComplianceView activeView={activeView} tasks={tasks} onToggle={toggleTask} />}
          {!(["Dashboard", "Employees", "Attendance", "Payroll overview", "Payroll runs", "Payslips", "Compliance dashboard", "Obligations & tasks", "Compliance calendar"] as ViewKey[]).includes(activeView) && <ComingSoonView view={activeView} onNavigate={goTo} />}
        </main>
      </div>

      <Dialog open={addEmployeeOpen} onOpenChange={setAddEmployeeOpen}>
        <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-[500px]">
          <DialogHeader><DialogTitle>Add employee</DialogTitle><DialogDescription>Create a new employee record for Northstar Technologies.</DialogDescription></DialogHeader>
          <form onSubmit={createEmployee} className="space-y-4 py-2">
            <Field label="Full name"><Input required value={newEmployeeName} onChange={(event) => setNewEmployeeName(event.target.value)} placeholder="e.g. Meera Iyer" /></Field>
            <Field label="Designation"><Input required value={newEmployeeRole} onChange={(event) => setNewEmployeeRole(event.target.value)} placeholder="e.g. Product Manager" /></Field>
            <Field label="Department"><select className="h-9 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus-visible:ring-1 focus-visible:ring-ring" value={newEmployeeDepartment} onChange={(event) => setNewEmployeeDepartment(event.target.value)}>{["Engineering", "Finance", "People & Culture", "Sales", "Product & Design", "Legal & Compliance", "Operations"].map((department) => <option key={department}>{department}</option>)}</select></Field>
            <DialogFooter className="pt-2"><Button type="button" variant="outline" onClick={() => setAddEmployeeOpen(false)}>Cancel</Button><Button type="submit"><Users className="h-4 w-4" />Create employee</Button></DialogFooter>
          </form>
        </DialogContent>
      </Dialog>

      <Dialog open={notificationsOpen} onOpenChange={setNotificationsOpen}>
        <DialogContent className="max-h-[82vh] overflow-y-auto sm:max-w-[460px]">
          <DialogHeader><DialogTitle>Notifications</DialogTitle><DialogDescription>{unreadCount} items need your attention.</DialogDescription></DialogHeader>
          <div className="space-y-1">{tasks.filter((task) => task.status === "Overdue" || task.status === "Due soon").map((task) => <button key={task.id} onClick={() => { goTo("Obligations & tasks"); setNotificationsOpen(false); }} className="flex w-full gap-3 rounded-lg p-3 text-left hover:bg-muted"><span className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-md ${task.status === "Overdue" ? "bg-critical-soft text-critical" : "bg-warning-soft text-warning"}`}><Clock3 className="h-4 w-4" /></span><span><span className="block text-sm font-medium">{task.title}</span><span className="mt-1 block text-xs text-muted-foreground">{task.status} · Due {task.due} · {task.location}</span></span></button>)}</div>
          <Button variant="outline" onClick={() => { goTo("Compliance dashboard"); setNotificationsOpen(false); }}>Open compliance dashboard<ArrowRight className="h-4 w-4" /></Button>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function DashboardView({ employees, tasks, runs, activities, onNavigate, onToggleTask }: { employees: Employee[]; tasks: ComplianceTask[]; runs: typeof seedPayrollRuns; activities: ActivityItem[]; onNavigate: (view: ViewKey) => void; onToggleTask: (task: ComplianceTask) => void }) {
  const active = employees.filter((employee) => employee.status === "Active").length;
  const overdue = tasks.filter((task) => task.status === "Overdue").length;
  const pending = tasks.filter((task) => task.status === "Due soon" || task.status === "Upcoming").length;
  const pendingTask = tasks.find((task) => task.status === "Due soon" || task.status === "Overdue");
  return <div className="space-y-7">
    <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><div className="mb-2 flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-success" /><span className="text-xs font-medium text-muted-foreground">All systems operational</span></div><h1 className="text-2xl font-semibold tracking-tight sm:text-[28px]">Good morning, Ananya <span aria-hidden="true">✦</span></h1><p className="mt-1.5 text-sm text-muted-foreground">Here’s what’s happening across your organisation today.</p></div><div className="flex flex-wrap items-center gap-2"><span className="text-xs text-muted-foreground">{todayIndian()}</span><Button variant="outline" size="sm" className="bg-card" onClick={() => toast.message("Showing April 2026 – March 2027 financial year")}>FY 2026–27<ChevronDown className="h-3.5 w-3.5" /></Button><Button size="sm" onClick={() => onNavigate("Employees")}><Users className="h-4 w-4" />Employee directory</Button></div></div>
    <div className="grid gap-4 sm:grid-cols-2 2xl:grid-cols-4"><MetricCard title="Active employees" value={active.toLocaleString("en-IN")} note="4.8%" direction="up" icon={Users} color="blue" /><MetricCard title="Monthly payroll" value="₹4.82 Cr" note="2.4%" direction="up" icon={Wallet} color="teal" /><MetricCard title="Pending compliance" value={pending.toString().padStart(2, "0")} note="2 due this week" direction="flat" icon={FileCheck2} color="amber" /><MetricCard title="Overdue tasks" value={overdue.toString().padStart(2, "0")} note="Needs attention" direction="down" icon={Clock3} color="red" /></div>
    <div className="grid gap-5 2xl:grid-cols-[minmax(0,1.8fr)_minmax(320px,0.9fr)]">
      <section className="portal-surface min-w-0 rounded-lg p-5 sm:p-6"><div className="mb-6 flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-base font-semibold">Payroll overview</h2><p className="mt-1 text-xs text-muted-foreground">Monthly payroll cost · FY 2026–27</p></div><Button variant="outline" size="sm" className="bg-card" onClick={() => onNavigate("Payroll overview")}>View payroll<ArrowRight className="h-3.5 w-3.5" /></Button></div><div className="mb-4 flex flex-wrap items-end gap-x-5 gap-y-2"><strong className="tabular-nums text-2xl font-semibold">₹4.82 Cr</strong><span className="inline-flex items-center gap-1 pb-0.5 text-xs font-medium text-success"><ArrowUpRight className="h-3.5 w-3.5" />2.4%<span className="font-normal text-muted-foreground">vs last month</span></span></div><div className="h-[220px] w-full"><ResponsiveContainer width="100%" height="100%"><AreaChart data={payrollTrend} margin={{ top: 8, right: 8, bottom: 0, left: 4 }}><defs><linearGradient id="payrollFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-primary)" stopOpacity={0.2} /><stop offset="95%" stopColor="var(--color-primary)" stopOpacity={0.01} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--color-border)" strokeDasharray="3 5" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "var(--color-muted-foreground)", fontSize: 11 }} dy={8} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "var(--color-muted-foreground)", fontSize: 11 }} tickFormatter={(value: number) => `₹${value}L`} width={49} /><ChartTooltip cursor={{ stroke: "var(--color-border)", strokeDasharray: "4 4" }} contentStyle={{ borderRadius: 8, borderColor: "var(--color-border)", backgroundColor: "var(--color-card)", fontSize: 12 }} formatter={(value) => [`₹${value} L`, "Payroll cost"]} /><Area type="monotone" dataKey="cost" stroke="var(--color-primary)" strokeWidth={2.5} fill="url(#payrollFill)" activeDot={{ r: 4, strokeWidth: 0, fill: "var(--color-primary)" }} /></AreaChart></ResponsiveContainer></div><div className="mt-5 flex flex-wrap gap-x-7 gap-y-3 border-t pt-4"><div><p className="text-[11px] text-muted-foreground">NOVEMBER RUN</p><p className="mt-1 text-sm font-semibold">{runs.find((run) => run.period.startsWith("November"))?.status ?? "Processing"}</p></div><div><p className="text-[11px] text-muted-foreground">EMPLOYEES PROCESSED</p><p className="mt-1 text-sm font-semibold tabular-nums">1,251 <span className="text-xs font-normal text-muted-foreground">of 1,256</span></p></div><div><p className="text-[11px] text-muted-foreground">NEXT PAY DATE</p><p className="mt-1 text-sm font-semibold">30 Nov 2026</p></div></div></section>
      <section className="portal-surface rounded-lg p-5 sm:p-6"><div className="mb-4 flex items-start justify-between"><div><h2 className="text-base font-semibold">Compliance health</h2><p className="mt-1 text-xs text-muted-foreground">Across all locations · November</p></div><Button variant="ghost" size="icon" className="h-8 w-8" aria-label="View compliance details" onClick={() => onNavigate("Compliance dashboard")}><ArrowRight className="h-4 w-4" /></Button></div><div className="flex items-center gap-4"><div className="relative h-[132px] w-[132px] shrink-0"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={[{ name: "Compliant", value: 92 }, { name: "Needs attention", value: 8 }]} dataKey="value" innerRadius={46} outerRadius={59} startAngle={90} endAngle={-270} strokeWidth={0} paddingAngle={2}><Cell fill="var(--color-success)" /><Cell fill="var(--color-warning)" /></Pie></PieChart></ResponsiveContainer><div className="pointer-events-none absolute inset-0 flex flex-col items-center justify-center"><span className="text-[26px] font-semibold tabular-nums">92%</span><span className="text-[10px] text-muted-foreground">health score</span></div></div><div className="min-w-0 flex-1 space-y-3"><ComplianceLegend color="bg-success" label="Compliant" count="38" /><ComplianceLegend color="bg-warning" label="Pending" count={pending.toString()} /><ComplianceLegend color="bg-critical" label="Overdue" count={overdue.toString()} /></div></div><div className="mt-4 rounded-lg bg-warning-soft/60 p-3"><div className="flex gap-2.5"><span className="mt-0.5 text-warning"><Clock3 className="h-4 w-4" /></span><div className="min-w-0"><p className="text-xs font-semibold">{pendingTask?.title ?? "No urgent obligations"}</p><p className="mt-1 text-[11px] text-muted-foreground">{pendingTask ? `${pendingTask.status} · ${pendingTask.due} · ${pendingTask.location}` : "All obligations are on track"}</p></div></div><Button variant="link" className="mt-1 h-7 px-0 text-xs text-warning" onClick={() => onNavigate("Obligations & tasks")}>Review obligations<ArrowRight className="h-3 w-3" /></Button></div></section>
    </div>
    <div className="grid gap-5 2xl:grid-cols-[minmax(0,1.2fr)_minmax(360px,0.8fr)]">
      <section className="portal-surface min-w-0 rounded-lg p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-base font-semibold">Workforce distribution</h2><p className="mt-1 text-xs text-muted-foreground">Employees by department</p></div><Button variant="ghost" size="icon" className="h-8 w-8" aria-label="View employees" onClick={() => onNavigate("Employees")}><ArrowRight className="h-4 w-4" /></Button></div><div className="h-[200px]"><ResponsiveContainer width="100%" height="100%"><BarChart data={departmentDistribution} layout="vertical" margin={{ top: 0, right: 12, left: 4, bottom: 0 }}><CartesianGrid horizontal={false} stroke="var(--color-border)" strokeDasharray="3 5" /><XAxis type="number" hide /><YAxis type="category" dataKey="name" axisLine={false} tickLine={false} width={112} tick={{ fill: "var(--color-muted-foreground)", fontSize: 11 }} /><ChartTooltip cursor={{ fill: "var(--color-muted)" }} contentStyle={{ borderRadius: 8, borderColor: "var(--color-border)", backgroundColor: "var(--color-card)", fontSize: 12 }} formatter={(value) => [value, "Employees"]} /><Bar dataKey="count" fill="var(--color-primary)" radius={[0, 4, 4, 0]} barSize={16}>{departmentDistribution.map((entry, index) => <Cell key={entry.name} fill={index === 0 ? "var(--color-primary)" : index === 1 ? "var(--color-information)" : index === 2 ? "var(--color-success)" : "var(--color-chart-3)"} />)}</Bar></BarChart></ResponsiveContainer></div><div className="mt-2 flex flex-wrap gap-2 border-t pt-4">{["Bengaluru", "Mumbai", "Hyderabad", "Other locations"].map((city, index) => <span key={city} className="inline-flex items-center gap-1.5 rounded-md bg-muted/70 px-2.5 py-1.5 text-[11px] text-muted-foreground"><span className={`h-1.5 w-1.5 rounded-full ${["bg-primary", "bg-information", "bg-success", "bg-chart-3"][index]}`} />{city}<span className="font-semibold text-foreground">{[428, 310, 186, 327][index]}</span></span>)}</div></section>
      <section className="portal-surface min-w-0 rounded-lg p-5 sm:p-6"><div className="mb-4 flex items-start justify-between"><div><h2 className="text-base font-semibold">Recent activity</h2><p className="mt-1 text-xs text-muted-foreground">Latest updates across your organisation</p></div><Button variant="ghost" size="sm" className="text-xs text-muted-foreground" onClick={() => onNavigate("Audit trail")}>View all<ArrowRight className="h-3.5 w-3.5" /></Button></div><div className="divide-y">{activities.slice(0, 5).map((activity, index) => <ActivityRow activity={activity} key={`${activity.title}-${activity.time}-${index}`} />)}</div></section>
    </div>
    <section className="portal-surface rounded-lg p-5 sm:p-6"><div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-base font-semibold">Upcoming obligations</h2><p className="mt-1 text-xs text-muted-foreground">Stay ahead of your compliance calendar.</p></div><Button variant="outline" size="sm" className="bg-card" onClick={() => onNavigate("Obligations & tasks")}>All obligations<ArrowRight className="h-3.5 w-3.5" /></Button></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left"><thead><tr className="border-b text-[10px] font-medium uppercase tracking-wide text-muted-foreground"><th className="pb-3 pr-4">Obligation</th><th className="pb-3 pr-4">Location</th><th className="pb-3 pr-4">Due date</th><th className="pb-3 pr-4">Owner</th><th className="pb-3 pr-4">Status</th><th className="pb-3 text-right">Action</th></tr></thead><tbody>{tasks.slice(0, 4).map((task) => <tr key={task.id} className="border-b last:border-0"><td className="py-3 pr-4"><div className="flex items-center gap-2.5"><span className={`flex h-8 w-8 items-center justify-center rounded-md text-[10px] font-bold ${task.category === "PF" ? "bg-information-soft text-information" : task.category === "ESI" ? "bg-success-soft text-success" : task.category === "TDS" ? "bg-warning-soft text-warning" : "bg-accent text-accent-foreground"}`}>{task.category}</span><span className="min-w-0"><span className="block truncate text-xs font-medium">{task.title}</span><span className="mt-0.5 block truncate text-[10px] text-muted-foreground">{task.id}</span></span></div></td><td className="py-3 pr-4 text-xs text-muted-foreground">{task.location}</td><td className="py-3 pr-4 text-xs tabular-nums">{task.due}</td><td className="py-3 pr-4 text-xs">{task.owner}</td><td className="py-3 pr-4"><StatusPill>{task.status}</StatusPill></td><td className="py-3 text-right"><Button variant="ghost" size="sm" className="h-8 text-xs text-muted-foreground" onClick={() => task.status !== "Completed" ? onToggleTask(task) : onNavigate("Obligations & tasks")}>{task.status === "Completed" ? "Details" : "Mark done"}{task.status === "Completed" && <ArrowRight className="h-3 w-3" />}</Button></td></tr>)}</tbody></table></div></section>
  </div>;
}

function ComplianceLegend({ color, label, count }: { color: string; label: string; count: string }) {
  return <div className="flex items-center justify-between gap-3"><span className="flex items-center gap-2 text-xs text-muted-foreground"><span className={`h-2 w-2 rounded-full ${color}`} />{label}</span><span className="text-sm font-semibold tabular-nums">{count}</span></div>;
}

function ActivityRow({ activity }: { activity: ActivityItem }) {
  const Icon = activity.icon === "wallet" ? Wallet : activity.icon === "shield" ? ShieldCheck : Users;
  const color = activity.icon === "wallet" ? "bg-information-soft text-information" : activity.icon === "shield" ? "bg-success-soft text-success" : "bg-accent text-accent-foreground";
  return <div className="flex items-center gap-3 py-3"><span className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-full ${color}`}><Icon className="h-3.5 w-3.5" /></span><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium">{activity.title}</p><p className="mt-0.5 truncate text-[10px] text-muted-foreground">{activity.detail}</p></div><span className="shrink-0 text-[10px] text-muted-foreground">{activity.time}</span></div>;
}

function EmployeesView({ employees, total, search, onSearch, department, onDepartment, status, onStatus, onAdd, onExport, onReset }: { employees: Employee[]; total: number; search: string; onSearch: (value: string) => void; department: string; onDepartment: (value: string) => void; status: string; onStatus: (value: string) => void; onAdd: () => void; onExport: () => void; onReset: () => void }) {
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs text-muted-foreground">Workforce / Directory</p><h1 className="text-2xl font-semibold tracking-tight">Employees</h1><p className="mt-1.5 text-sm text-muted-foreground">Manage employee records across your organisation.</p></div><Button onClick={onAdd}><Users className="h-4 w-4" />Add employee</Button></div>
    <div className="grid gap-3 sm:grid-cols-3"><SmallStat label="Total employees" value={total.toLocaleString("en-IN")} icon={Users} /><SmallStat label="Active" value={(total - 2).toLocaleString("en-IN")} icon={CheckCircle2} /><SmallStat label="Onboarding" value="05" icon={Sparkles} /></div>
    <section className="portal-surface overflow-hidden rounded-lg"><div className="flex flex-col gap-3 border-b p-4 sm:flex-row sm:items-center sm:justify-between"><div className="relative w-full sm:max-w-[280px]"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input aria-label="Search directory" placeholder="Search by name, ID or role" value={search} onChange={(event) => onSearch(event.target.value)} className="pl-9" /></div><div className="flex flex-wrap items-center gap-2"><label className="sr-only" htmlFor="department-filter">Department</label><select id="department-filter" className="h-9 rounded-md border border-input bg-card px-3 text-xs outline-none" value={department} onChange={(event) => onDepartment(event.target.value)}>{["All departments", ...new Set([...seedEmployees.map((employee) => employee.department)])].map((item) => <option key={item}>{item}</option>)}</select><label className="sr-only" htmlFor="status-filter">Status</label><select id="status-filter" className="h-9 rounded-md border border-input bg-card px-3 text-xs outline-none" value={status} onChange={(event) => onStatus(event.target.value)}>{["All statuses", "Active", "On leave", "Probation"].map((item) => <option key={item}>{item}</option>)}</select><Button variant="outline" size="sm" onClick={onReset}><Filter className="h-3.5 w-3.5" />Reset</Button><Button variant="outline" size="sm" onClick={onExport}><Download className="h-3.5 w-3.5" /><span className="hidden sm:inline">Export CSV</span></Button></div></div>
    <div className="overflow-x-auto"><table className="w-full min-w-[900px] text-left"><thead><tr className="border-b bg-muted/40 text-[10px] font-medium uppercase tracking-wide text-muted-foreground"><th className="px-5 py-3">Employee</th><th className="px-4 py-3">Department</th><th className="px-4 py-3">Location</th><th className="px-4 py-3">Employment</th><th className="px-4 py-3">Joined</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Actions</th></tr></thead><tbody>{employees.map((employee) => <tr key={employee.id} className="border-b last:border-0 hover:bg-muted/25"><td className="px-5 py-3.5"><div className="flex items-center gap-3"><InitialAvatar name={employee.name} initials={employee.initials} size="sm" /><div className="min-w-0"><p className="truncate text-xs font-semibold">{employee.name}</p><p className="mt-0.5 truncate text-[10px] text-muted-foreground">{employee.id} · {employee.role}</p></div></div></td><td className="px-4 py-3.5 text-xs">{employee.department}</td><td className="px-4 py-3.5 text-xs text-muted-foreground">{employee.location}</td><td className="px-4 py-3.5 text-xs text-muted-foreground">{employee.type}</td><td className="px-4 py-3.5 text-xs tabular-nums text-muted-foreground">{employee.joined}</td><td className="px-4 py-3.5"><StatusPill>{employee.status}</StatusPill></td><td className="px-4 py-3.5 text-right"><Button variant="ghost" size="icon" className="h-8 w-8" aria-label={`View ${employee.name}`} onClick={() => toast.message(`${employee.name} · ${employee.role}`, { description: `${employee.email} · ${employee.location}` })}><MoreHorizontal className="h-4 w-4" /></Button></td></tr>)}</tbody></table>
      {employees.length === 0 && <div className="px-5 py-16 text-center"><Users className="mx-auto h-8 w-8 text-muted-foreground/50" /><p className="mt-3 text-sm font-medium">No employees match those filters</p><p className="mt-1 text-xs text-muted-foreground">Try changing your search or filters.</p><Button variant="outline" size="sm" className="mt-4" onClick={onReset}>Clear filters</Button></div>}
    </div><div className="flex flex-wrap items-center justify-between gap-3 border-t px-5 py-3 text-xs text-muted-foreground"><span>Showing <strong className="text-foreground">{employees.length ? 1 : 0}–{employees.length}</strong> of <strong className="text-foreground">{employees.length}</strong> employees</span><div className="flex items-center gap-2"><span>Rows per page</span><span className="rounded border px-2 py-1 text-foreground">10</span><Button variant="outline" size="icon" className="h-7 w-7" disabled aria-label="Previous page"><ChevronLeft className="h-3.5 w-3.5" /></Button><span>1</span><Button variant="outline" size="icon" className="h-7 w-7" disabled aria-label="Next page"><ChevronRight className="h-3.5 w-3.5" /></Button></div></div></section>
  </div>;
}

function SmallStat({ label, value, icon: Icon }: { label: string; value: string; icon: typeof Users }) {
  return <div className="portal-surface flex items-center gap-3 rounded-lg p-4"><span className="flex h-9 w-9 items-center justify-center rounded-md bg-information-soft text-information"><Icon className="h-4 w-4" /></span><div><p className="text-[11px] text-muted-foreground">{label}</p><p className="mt-0.5 text-lg font-semibold tabular-nums">{value}</p></div></div>;
}

function AttendanceView({ employees, month, onMonth, marks, onMark }: { employees: Employee[]; month: string; onMonth: (month: string) => void; marks: Record<string, string>; onMark: (key: string, status: string) => void }) {
  const days = Array.from({ length: 14 }, (_, index) => index + 1);
  const options = ["October 2026", "November 2026", "December 2026"];
  const getStatus = (employee: Employee, day: number) => marks[`${employee.id}-${day}`] ?? ((day + employee.id.charCodeAt(employee.id.length - 1)) % 13 === 0 ? "A" : (day + employee.name.length) % 11 === 0 ? "L" : "P");
  const summary = { present: 1_186, absent: 12, leave: 41 };
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs text-muted-foreground">Workforce / Attendance</p><h1 className="text-2xl font-semibold tracking-tight">Attendance</h1><p className="mt-1.5 text-sm text-muted-foreground">Review and update monthly attendance records.</p></div><select aria-label="Attendance month" className="h-9 w-fit rounded-md border border-input bg-card px-3 text-sm" value={month} onChange={(event) => onMonth(event.target.value)}>{options.map((item) => <option key={item}>{item}</option>)}</select></div><div className="grid gap-3 sm:grid-cols-3"><SmallStat label="Present today" value="1,186" icon={CheckCircle2} /><SmallStat label="Absent today" value="12" icon={Clock3} /><SmallStat label="On leave" value="41" icon={CalendarDays} /></div><section className="portal-surface overflow-hidden rounded-lg"><div className="flex flex-wrap items-center justify-between gap-3 border-b p-4"><div><h2 className="text-sm font-semibold">Daily attendance</h2><p className="mt-1 text-xs text-muted-foreground">Select a day cell to cycle status: Present → Absent → Leave</p></div><div className="flex gap-3 text-[10px] text-muted-foreground"><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-full bg-success" />Present</span><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-full bg-critical" />Absent</span><span className="flex items-center gap-1"><i className="h-2 w-2 rounded-full bg-warning" />Leave</span></div></div><div className="overflow-x-auto"><table className="w-full min-w-[900px] text-center"><thead><tr className="border-b bg-muted/40 text-[10px] text-muted-foreground"><th className="sticky left-0 z-10 bg-muted/90 px-4 py-3 text-left font-medium">Employee</th>{days.map((day) => <th key={day} className="min-w-10 px-1 py-3 font-medium"><span className="block">{[1, 8].includes(day) ? "SUN" : "MON"}</span><span className="mt-1 block text-xs text-foreground">{day}</span></th>)}</tr></thead><tbody>{employees.slice(0, 7).map((employee) => <tr key={employee.id} className="border-b last:border-0"><td className="sticky left-0 z-10 bg-card px-4 py-2 text-left"><div className="flex items-center gap-2.5"><InitialAvatar name={employee.name} initials={employee.initials} size="sm" /><span><span className="block text-xs font-medium">{employee.name}</span><span className="block text-[10px] text-muted-foreground">{employee.id}</span></span></div></td>{days.map((day) => { const status = getStatus(employee, day); const className = status === "P" ? "bg-success-soft text-success" : status === "A" ? "bg-critical-soft text-critical" : "bg-warning-soft text-warning"; return <td key={day} className="px-1 py-2"><button aria-label={`${employee.name}, day ${day}, ${status === "P" ? "present" : status === "A" ? "absent" : "leave"}`} className={`mx-auto flex h-7 w-7 items-center justify-center rounded-md text-[10px] font-semibold transition-colors hover:ring-2 hover:ring-ring`} onClick={() => { const next = status === "P" ? "A" : status === "A" ? "L" : "P"; onMark(`${employee.id}-${day}`, next); toast.success(`${employee.name} marked ${next === "P" ? "present" : next === "A" ? "absent" : "on leave"} for ${day} Nov`); }}><span className={className}>{status}</span></button></td>; })}</tr>)}</tbody></table></div><div className="border-t px-4 py-3 text-xs text-muted-foreground">Showing 1–{Math.min(7, employees.length)} of {employees.length} employees · {month} · Sample records</div></section></div>;
}

function PayrollView({ activeView, runs, onStatus }: { activeView: ViewKey; runs: typeof seedPayrollRuns; onStatus: (id: string, status: PayrollStatus) => void }) {
  const [selectedPeriod, setSelectedPeriod] = useState("November 2026");
  const [wizardStep, setWizardStep] = useState(0);
  const [wizardOpen, setWizardOpen] = useState(false);
  const [payrollTab, setPayrollTab] = useState("All runs");
  const completedRuns = runs.filter((run) => run.status === "Finalized").length;
  const awaitingApproval = runs.filter((run) => run.status === "Awaiting approval").length;
  const visibleRuns = runs.filter((run) => payrollTab === "All runs" || run.status === payrollTab);
  const startRun = () => { setSelectedPeriod("November 2026"); setWizardStep(1); setWizardOpen(true); };
  const nextStep = () => { if (wizardStep >= 4) { setWizardOpen(false); setWizardStep(0); onStatus("PR-2026-11", "Processing"); toast.success("November payroll run started"); return; } setWizardStep((step) => step + 1); };
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs text-muted-foreground">Payroll / {activeView === "Payslips" ? "Payslips" : "Payroll runs"}</p><h1 className="text-2xl font-semibold tracking-tight">{activeView === "Payslips" ? "Payslips" : "Payroll management"}</h1><p className="mt-1.5 text-sm text-muted-foreground">{activeView === "Payslips" ? "Review payroll statements for each pay period." : "Monitor pay runs and their approval status."}</p></div><Button onClick={startRun}><Wallet className="h-4 w-4" />Run payroll</Button></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><SmallStat label="Monthly payroll" value="₹4.82 Cr" icon={Wallet} /><SmallStat label="Employees processed" value="1,251" icon={Users} /><SmallStat label="Awaiting approval" value={String(awaitingApproval).padStart(2, "0")} icon={Clock3} /><SmallStat label="Completed runs" value={String(completedRuns).padStart(2, "0")} icon={CheckCircle2} /></div><div className="grid gap-5 2xl:grid-cols-[minmax(0,1.5fr)_minmax(300px,0.8fr)]"><section className="portal-surface min-w-0 rounded-lg p-5"><SectionTitle title="Payroll cost trend" action="Download report" onAction={() => toast.success("Payroll summary report is ready")} /><div className="h-[230px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={payrollTrend} margin={{ top: 8, right: 10, bottom: 0, left: 4 }}><defs><linearGradient id="payrollTrendFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--color-information)" stopOpacity={0.18} /><stop offset="100%" stopColor="var(--color-information)" stopOpacity={0} /></linearGradient></defs><CartesianGrid vertical={false} stroke="var(--color-border)" strokeDasharray="3 5" /><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{ fill: "var(--color-muted-foreground)", fontSize: 11 }} dy={8} /><YAxis axisLine={false} tickLine={false} tick={{ fill: "var(--color-muted-foreground)", fontSize: 11 }} tickFormatter={(value: number) => `₹${value}L`} width={48} /><ChartTooltip contentStyle={{ borderRadius: 8, borderColor: "var(--color-border)", backgroundColor: "var(--color-card)", fontSize: 12 }} formatter={(value) => [`₹${value} L`, "Monthly payroll"]} /><Area type="monotone" dataKey="cost" stroke="var(--color-information)" strokeWidth={2.5} fill="url(#payrollTrendFill)" /></AreaChart></ResponsiveContainer></div></section><section className="portal-surface rounded-lg p-5"><SectionTitle title="Run progress" /><div className="flex items-center justify-between"><div><p className="text-xs text-muted-foreground">November 2026</p><p className="mt-1 text-2xl font-semibold">1,251 <span className="text-sm font-normal text-muted-foreground">/ 1,256</span></p></div><StatusPill>{runs.find((run) => run.period.startsWith("November"))?.status ?? "Processing"}</StatusPill></div><Progress value={99} className="mt-4 h-2" /><p className="mt-2 text-[11px] text-muted-foreground">99.6% of employee records processed</p><div className="mt-5 divide-y border-t">{[{ label: "Attendance validated", done: true }, { label: "Salary inputs reviewed", done: true }, { label: "Exception review", done: false }, { label: "Approval", done: false }].map((step) => <div key={step.label} className="flex items-center gap-2.5 py-3 text-xs"><span className={`flex h-5 w-5 items-center justify-center rounded-full ${step.done ? "bg-success-soft text-success" : "bg-muted text-muted-foreground"}`}>{step.done ? <Check className="h-3 w-3" /> : <span className="h-1.5 w-1.5 rounded-full bg-current" />}</span><span className={step.done ? "text-muted-foreground" : "font-medium"}>{step.label}</span></div>)}</div><Button variant="outline" className="mt-2 w-full" onClick={startRun}>Continue November run<ArrowRight className="h-4 w-4" /></Button></section></div><section className="portal-surface overflow-hidden rounded-lg"><div className="flex flex-col gap-3 border-b p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-sm font-semibold">Payroll runs</h2><p className="mt-1 text-xs text-muted-foreground">{runs.length} pay periods · FY 2026–27</p></div><Button variant="outline" size="sm" onClick={() => toast.success("Payroll register exported as CSV") }><Download className="h-3.5 w-3.5" />Export</Button></div><Tabs value={payrollTab} onValueChange={setPayrollTab} className="w-full"><div className="overflow-x-auto px-4 pt-3"><TabsList className="h-8 w-max"><TabsTrigger value="All runs" className="text-xs">All runs</TabsTrigger><TabsTrigger value="Processing" className="text-xs">Processing</TabsTrigger><TabsTrigger value="Awaiting approval" className="text-xs">Awaiting approval</TabsTrigger><TabsTrigger value="Needs review" className="text-xs">Needs review</TabsTrigger><TabsTrigger value="Finalized" className="text-xs">Finalized</TabsTrigger></TabsList></div><TabsContent value={payrollTab} className="mt-0"><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left"><thead><tr className="border-b text-[10px] font-medium uppercase tracking-wide text-muted-foreground"><th className="px-5 py-3">Payroll period</th><th className="px-4 py-3">Employees</th><th className="px-4 py-3">Gross payroll</th><th className="px-4 py-3">Deductions</th><th className="px-4 py-3">Net payroll</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Action</th></tr></thead><tbody>{visibleRuns.map((run) => <tr key={run.id} className="border-b last:border-0 hover:bg-muted/25"><td className="px-5 py-3.5"><p className="text-xs font-semibold">{run.period}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{run.id}</p></td><td className="px-4 py-3.5 text-xs tabular-nums">{run.employees.toLocaleString("en-IN")}</td><td className="px-4 py-3.5 text-xs tabular-nums">{compactINR(run.gross)}</td><td className="px-4 py-3.5 text-xs tabular-nums text-muted-foreground">{compactINR(run.deductions)}</td><td className="px-4 py-3.5 text-xs font-semibold tabular-nums">{compactINR(run.net)}</td><td className="px-4 py-3.5"><StatusPill>{run.status}</StatusPill></td><td className="px-4 py-3.5 text-right">{run.status === "Processing" ? <Button variant="outline" size="sm" className="h-8 text-[11px]" onClick={() => onStatus(run.id, "Needs review")}>Review</Button> : run.status === "Needs review" ? <Button size="sm" className="h-8 text-[11px]" onClick={() => onStatus(run.id, "Awaiting approval")}>Submit</Button> : run.status === "Awaiting approval" ? <Button size="sm" className="h-8 text-[11px]" onClick={() => onStatus(run.id, "Finalized")}>Approve</Button> : <Button variant="ghost" size="icon" className="h-8 w-8" aria-label={`Download payslips for ${run.period}`} onClick={() => toast.success(`${run.period} payslips prepared`)}><Download className="h-3.5 w-3.5" /></Button>}</td></tr>)}</tbody></table></div>{visibleRuns.length === 0 && <p className="p-10 text-center text-sm text-muted-foreground">No payroll runs in this status.</p>}</TabsContent></Tabs><div className="border-t px-5 py-3 text-xs text-muted-foreground">Statutory values are illustrative sample data, not certified legal calculations.</div></section>
    <Dialog open={wizardOpen} onOpenChange={setWizardOpen}><DialogContent className="sm:max-w-[540px]"><DialogHeader><DialogTitle>{wizardStep === 4 ? "Payroll submitted" : "Create payroll run"}</DialogTitle><DialogDescription>{wizardStep === 4 ? "The run is ready for approval." : "November 2026 · Northstar Technologies · Sample data"}</DialogDescription></DialogHeader>{wizardStep < 4 ? <><div className="flex items-center gap-1.5 py-2">{[1, 2, 3].map((step) => <span key={step} className={`h-1.5 flex-1 rounded-full ${step <= Math.ceil(wizardStep / 1.34) ? "bg-primary" : "bg-muted"}`} />)}</div><div className="min-h-44 rounded-lg bg-muted/45 p-5"><p className="text-xs font-medium text-muted-foreground">STEP {wizardStep} OF 3</p><h3 className="mt-2 text-lg font-semibold">{["Select period", "Review payroll inputs", "Validate the run"][Math.min(wizardStep - 1, 2)]}</h3><p className="mt-2 text-sm text-muted-foreground">{["Confirm the pay period and organisation before preparing payroll.", "Attendance and salary inputs are ready for 1,251 employees.", "Review the sample exceptions before submitting for approval."][Math.min(wizardStep - 1, 2)]}</p>{wizardStep === 1 && <label className="mt-5 block text-xs font-medium">Pay period<select className="mt-1.5 h-9 w-full rounded-md border border-input bg-card px-3 text-sm" value={selectedPeriod} onChange={(event) => setSelectedPeriod(event.target.value)}><option>November 2026</option><option>December 2026</option></select></label>}{wizardStep === 3 && <div className="mt-4 rounded-md border border-warning/30 bg-warning-soft p-3 text-xs text-warning">2 sample exceptions need review before payroll can be finalized.</div>}</div></> : <div className="rounded-lg bg-success-soft p-5"><div className="flex items-center gap-3"><CheckCircle2 className="h-7 w-7 text-success" /><div><p className="text-sm font-semibold">November run submitted</p><p className="mt-1 text-xs text-muted-foreground">Payroll is now in progress for 1,251 employees.</p></div></div></div>}<DialogFooter><Button variant="outline" onClick={() => { setWizardOpen(false); setWizardStep(0); }}>{wizardStep === 4 ? "Done" : "Cancel"}</Button>{wizardStep < 4 && <Button onClick={nextStep}>{wizardStep === 3 ? "Submit for approval" : "Continue"}<ArrowRight className="h-4 w-4" /></Button>}</DialogFooter></DialogContent></Dialog>
  </div>;
}

function ComplianceView({ activeView, tasks, onToggle }: { activeView: ViewKey; tasks: ComplianceTask[]; onToggle: (task: ComplianceTask) => void }) {
  const [taskFilter, setTaskFilter] = useState("All statuses");
  const [taskSearch, setTaskSearch] = useState("");
  const filteredTasks = tasks.filter((task) => (taskFilter === "All statuses" || task.status === taskFilter) && `${task.title} ${task.id} ${task.location} ${task.owner}`.toLowerCase().includes(taskSearch.toLowerCase()));
  const counts = { completed: tasks.filter((task) => task.status === "Completed").length + 36, pending: tasks.filter((task) => task.status === "Upcoming" || task.status === "Due soon").length, overdue: tasks.filter((task) => task.status === "Overdue").length };
  return <div className="space-y-6"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-xs text-muted-foreground">Compliance / Obligations</p><h1 className="text-2xl font-semibold tracking-tight">{activeView === "Compliance calendar" ? "Compliance calendar" : "Compliance overview"}</h1><p className="mt-1.5 text-sm text-muted-foreground">Track statutory obligations, due dates and supporting evidence.</p></div><Button variant="outline" onClick={() => toast.success("Compliance summary downloaded")}><Download className="h-4 w-4" />Export status</Button></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><SmallStat label="Health score" value="92 / 100" icon={ShieldCheck} /><SmallStat label="Compliant" value={String(counts.completed).padStart(2, "0")} icon={CheckCircle2} /><SmallStat label="Pending" value={String(counts.pending).padStart(2, "0")} icon={Clock3} /><SmallStat label="Overdue" value={String(counts.overdue).padStart(2, "0")} icon={Activity} /></div>{activeView === "Compliance calendar" && <CalendarPreview tasks={tasks} onSelect={(task) => toast.message(task.title, { description: `${task.status} · ${task.due} · ${task.owner}` })} />}<section className="portal-surface overflow-hidden rounded-lg"><div className="flex flex-col gap-3 border-b p-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="text-sm font-semibold">Compliance obligations</h2><p className="mt-1 text-xs text-muted-foreground">{tasks.length} sample obligations · FY 2026–27</p></div><div className="flex flex-wrap gap-2"><div className="relative"><Search className="absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-muted-foreground" /><Input aria-label="Search obligations" placeholder="Search obligations" className="h-9 w-full pl-8 sm:w-48" value={taskSearch} onChange={(event) => setTaskSearch(event.target.value)} /></div><select aria-label="Filter compliance status" className="h-9 rounded-md border border-input bg-card px-3 text-xs" value={taskFilter} onChange={(event) => setTaskFilter(event.target.value)}>{["All statuses", "Completed", "Upcoming", "Due soon", "Overdue"].map((item) => <option key={item}>{item}</option>)}</select></div></div><div className="overflow-x-auto"><table className="w-full min-w-[800px] text-left"><thead><tr className="border-b bg-muted/40 text-[10px] font-medium uppercase tracking-wide text-muted-foreground"><th className="px-5 py-3">Obligation</th><th className="px-4 py-3">Location</th><th className="px-4 py-3">Due date</th><th className="px-4 py-3">Owner</th><th className="px-4 py-3">Status</th><th className="px-4 py-3 text-right">Action</th></tr></thead><tbody>{filteredTasks.map((task) => <tr key={task.id} className="border-b last:border-0"><td className="px-5 py-3.5"><p className="text-xs font-medium">{task.title}</p><p className="mt-0.5 text-[10px] text-muted-foreground">{task.id} · {task.category} · {task.description}</p></td><td className="px-4 py-3.5 text-xs text-muted-foreground">{task.location}</td><td className="px-4 py-3.5 text-xs tabular-nums">{task.due}</td><td className="px-4 py-3.5 text-xs">{task.owner}</td><td className="px-4 py-3.5"><StatusPill>{task.status}</StatusPill></td><td className="px-4 py-3.5 text-right"><Button variant={task.status === "Completed" ? "outline" : "default"} size="sm" className="h-8 text-[11px]" onClick={() => onToggle(task)}>{task.status === "Completed" ? "Reopen" : "Mark complete"}</Button></td></tr>)}</tbody></table>{filteredTasks.length === 0 && <p className="p-10 text-center text-sm text-muted-foreground">No obligations match your search.</p>}</div><div className="border-t px-5 py-3 text-[11px] text-muted-foreground">Sample tracking data for demonstration only. This portal does not provide certified legal calculations or guarantee compliance.</div></section></div>;
}

function CalendarPreview({ tasks, onSelect }: { tasks: ComplianceTask[]; onSelect: (task: ComplianceTask) => void }) {
  const cells = Array.from({ length: 35 }, (_, index) => index - 1);
  const dueDays = new Map([[7, tasks.find((task) => task.status === "Completed")], [12, tasks.find((task) => task.status === "Overdue")], [18, tasks.find((task) => task.status === "Due soon")], [20, tasks.find((task) => task.status === "Upcoming")], [22, tasks.find((task) => task.status === "Upcoming")]]);
  return <section className="portal-surface grid gap-5 rounded-lg p-5 lg:grid-cols-[1.3fr_1fr]"><div><div className="mb-4 flex items-center justify-between"><div><h2 className="text-sm font-semibold">November 2026</h2><p className="mt-1 text-xs text-muted-foreground">Upcoming filing dates</p></div><div className="flex gap-1"><Button variant="outline" size="icon" className="h-8 w-8" aria-label="Previous month"><ChevronLeft className="h-4 w-4" /></Button><Button variant="outline" size="icon" className="h-8 w-8" aria-label="Next month"><ChevronRight className="h-4 w-4" /></Button></div></div><div className="grid grid-cols-7 gap-1 text-center">{["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => <span key={day} className="py-2 text-[10px] font-medium text-muted-foreground">{day}</span>)}{cells.map((day, index) => { const task = dueDays.get(day); return <button key={index} disabled={day < 1 || day > 30} onClick={() => task && onSelect(task)} className={`relative flex h-9 items-center justify-center rounded-md text-xs disabled:opacity-30 ${task ? "bg-warning-soft font-semibold text-warning hover:ring-1 hover:ring-warning" : "hover:bg-muted"}`}>{day < 1 ? 26 + day : day > 30 ? day - 30 : day}{task && <i className={`absolute bottom-1 h-1 w-1 rounded-full ${task.status === "Completed" ? "bg-success" : task.status === "Overdue" ? "bg-critical" : "bg-warning"}`} />}</button>; })}</div></div><div className="border-t pt-4 lg:border-l lg:border-t-0 lg:pl-5 lg:pt-0"><h3 className="mb-3 text-xs font-semibold">This month</h3><div className="space-y-2">{tasks.slice(0, 4).map((task) => <button key={task.id} onClick={() => onSelect(task)} className="flex w-full items-center gap-3 rounded-md p-2 text-left hover:bg-muted"><span className={`w-9 shrink-0 rounded-md py-1 text-center text-xs font-semibold ${task.status === "Completed" ? "bg-success-soft text-success" : task.status === "Overdue" ? "bg-critical-soft text-critical" : "bg-warning-soft text-warning"}`}>{task.due.split(" ")[0]}</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-medium">{task.title}</span><span className="mt-0.5 block text-[10px] text-muted-foreground">{task.location}</span></span><StatusPill>{task.status}</StatusPill></button>)}</div></div></section>;
}

function ComingSoonView({ view, onNavigate }: { view: ViewKey; onNavigate: (view: ViewKey) => void }) {
  const copy: Record<string, string> = {
    Departments: "Explore your organisation's department structure and headcount.",
    Audits: "Track audit plans, evidence and review progress across locations.",
    "Audit findings": "Follow corrective actions and resolution deadlines.",
    Documents: "A central place for employee, organisation and compliance documents.",
    Reports: "Review workforce, payroll and compliance reports.",
    "Users & roles": "Manage workspace access and permission groups.",
    Locations: "Manage office locations and their assigned obligations.",
    Settings: "Configure your organisation workspace.",
    "Audit trail": "A chronological record of key changes across your workspace.",
  };
  return <div className="space-y-6"><div><p className="mb-2 text-xs text-muted-foreground">Workspace / {view}</p><h1 className="text-2xl font-semibold tracking-tight">{view}</h1><p className="mt-1.5 text-sm text-muted-foreground">{copy[view]}</p></div><section className="portal-surface rounded-lg p-6 sm:p-8"><div className="grid gap-8 lg:grid-cols-[1fr_0.8fr]"><div><div className="flex h-11 w-11 items-center justify-center rounded-lg bg-information-soft text-information"><LockKeyhole className="h-5 w-5" /></div><h2 className="mt-5 text-lg font-semibold">{view} workspace</h2><p className="mt-2 max-w-md text-sm leading-6 text-muted-foreground">This area is part of the WorkforceOS demonstration. Seeded organisation data is available in the connected workforce, payroll and compliance views.</p><div className="mt-5 flex flex-wrap gap-2"><Button onClick={() => onNavigate("Dashboard")}>Back to dashboard<ArrowRight className="h-4 w-4" /></Button><Button variant="outline" onClick={() => onNavigate("Employees")}>Employee directory</Button></div></div><div className="rounded-lg bg-muted/50 p-5"><p className="text-xs font-semibold">Related workspace areas</p><div className="mt-3 divide-y">{(["Employees", "Payroll overview", "Compliance dashboard"] as ViewKey[]).map((area) => <button key={area} className="flex w-full items-center justify-between py-3 text-left text-xs hover:text-primary" onClick={() => onNavigate(area)}>{area}<ArrowRight className="h-3.5 w-3.5" /></button>)}</div><p className="mt-2 flex items-start gap-2 text-[11px] leading-5 text-muted-foreground"><CircleHelp className="mt-0.5 h-3.5 w-3.5 shrink-0" />Your demo records are illustrative; no real employee or statutory information is stored.</p></div></div></section></div>;
}

function Field({ label, children }: { label: string; children: ReactNode }) {
  return <label className="block space-y-1.5 text-xs font-medium">{label}{children}</label>;
}